#[no_mangle]
pub unsafe extern "C" fn match_positions(
    mut needle: *const c_char,
    mut haystack: *const c_char,
    mut positions: *mut size_t,
) -> score_t {
    let needle_view: &c_char = unsafe { // SAFETY: caller provides a valid C string pointer as required by the original API.
        &*needle
    };
    if *needle_view == 0 {
        return -::core::f32::INFINITY as score_t;
    }

    let mut match_1: match_struct = match_struct {
        needle_len: 0,
        haystack_len: 0,
        lower_needle: [0; 1024],
        lower_haystack: [0; 1024],
        match_bonus: [0.; 1024],
    };
    setup_match_struct(&raw mut match_1, needle, haystack);

    let n: c_int = match_1.needle_len;
    let m: c_int = match_1.haystack_len;

    if m > MATCH_MAX_LEN || n > m {
        return -::core::f32::INFINITY as score_t;
    } else if n == m {
        if !positions.is_null() {
            let mut i: c_int = 0;
            while i < n {
                unsafe { // SAFETY: positions is non-null here and caller is expected to provide space for n entries.
                    *positions.add(i as usize) = i as size_t;
                }
                i += 1;
            }
        }
        return ::core::f32::INFINITY as score_t;
    }

    let rows = n as usize;
    let cols = MATCH_MAX_LEN as usize;
    let total = rows.wrapping_mul(cols);
    let bytes = total.wrapping_mul(::core::mem::size_of::<score_t>());

    let m_ptr = malloc(bytes as size_t) as *mut score_t;
    let d_ptr = malloc(bytes as size_t) as *mut score_t;

    let mut i = 0usize;
    while i < rows {
        let d_row = unsafe { // SAFETY: d_ptr points to an allocation of at least total score_t elements; i < rows and each row has cols elements.
            d_ptr.add(i * cols)
        };
        let m_row = unsafe { // SAFETY: m_ptr points to an allocation of at least total score_t elements; i < rows and each row has cols elements.
            m_ptr.add(i * cols)
        };
        if i == 0 {
            match_row(&raw mut match_1, 0, d_row, m_row, d_row, m_row);
        } else {
            let prev_d = unsafe { // SAFETY: i > 0, so previous row exists within the same allocation.
                d_ptr.add((i - 1) * cols)
            };
            let prev_m = unsafe { // SAFETY: i > 0, so previous row exists within the same allocation.
                m_ptr.add((i - 1) * cols)
            };
            match_row(&raw mut match_1, i as c_int, d_row, m_row, prev_d, prev_m);
        }
        i += 1;
    }

    if !positions.is_null() {
        let mut match_required: c_int = 0;
        let mut i_1: c_int = n - 1;
        let mut j: c_int = m - 1;

        while i_1 >= 0 {
            let d_row = unsafe { // SAFETY: i_1 is in 0..n and each row has cols elements.
                d_ptr.add(i_1 as usize * cols)
            };
            let m_row = unsafe { // SAFETY: i_1 is in 0..n and each row has cols elements.
                m_ptr.add(i_1 as usize * cols)
            };
            let prev_d_row = if i_1 != 0 {
                unsafe { // SAFETY: i_1 > 0, so previous row exists within the allocation.
                    d_ptr.add((i_1 as usize - 1) * cols)
                }
            } else {
                ::core::ptr::null()
            };

            while j >= 0 {
                let ju = j as usize;
                let d_val = unsafe { // SAFETY: ju < m <= MATCH_MAX_LEN <= cols, so index is within the current row.
                    *d_row.add(ju)
                };
                if d_val != -::core::f32::INFINITY as score_t
                    && (match_required != 0
                        || d_val
                            == unsafe { // SAFETY: ju < m <= cols, so index is within the current row.
                                *m_row.add(ju)
                            })
                {
                    match_required = (i_1 != 0
                        && j != 0
                        && unsafe { // SAFETY: i_1 != 0 and j != 0 ensure previous row and previous column are valid.
                            *m_row.add(ju)
                                == *prev_d_row.add((j - 1) as usize) + SCORE_MATCH_CONSECUTIVE
                        }) as c_int;
                    let fresh1 = j;
                    j -= 1;
                    unsafe { // SAFETY: positions is non-null here and caller is expected to provide space for n entries.
                        *positions.add(i_1 as usize) = fresh1 as size_t;
                    }
                    break;
                } else {
                    j -= 1;
                }
            }
            i_1 -= 1;
        }
    }

    let result: score_t = unsafe { // SAFETY: n < = rows and m <= cols; n != 0 due to earlier empty-needle check.
        *m_ptr.add((n as usize - 1) * cols + (m as usize - 1))
    };

    free(m_ptr as *mut c_void);
    free(d_ptr as *mut c_void);
    result
}

